#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxDistance(vector<string>& words) {
        int n = words.size();
        int max_dist = 0;
        string first = words[0];
        string last = words[n - 1];
        for (int i = 0; i < n; ++i) {
            if (words[i] != first) max_dist = max(max_dist, i);
            if (words[i] != last) max_dist = max(max_dist, n - 1 - i);
        }
        return max_dist;
    }
};

class Solution {
    public int maxDistance(String[] words) {
        int n = words.length;
        int maxDist = 0;
        String first = words[0];
        String last = words[n - 1];
        for (int i = 0; i < n; i++) {
            if (!words[i].equals(first)) maxDist = Math.max(maxDist, i);
            if (!words[i].equals(last)) maxDist = Math.max(maxDist, n - 1 - i);
        }
        return maxDist;
    }
}

var maxDistance = function(words) {
    const n = words.length;
    let maxDist = 0;
    const first = words[0];
    const last = words[n - 1];
    for (let i = 0; i < n; i++) {
        if (words[i] !== first) maxDist = Math.max(maxDist, i);
        if (words[i] !== last) maxDist = Math.max(maxDist, n - 1 - i);
    }
    return maxDist;
};
